import { Chart, registerables } from 'chart.js';
Chart.register(...registerables);
let chart;
const series=[
 {label:'Image',color:'#edc04c',data:[0,110,680,1620,740,90]},
 {label:'Classic',color:'#50c3a2',data:[0,95,540,1290,600,70]},
 {label:'Audio',color:'#80b6ef',data:[0,70,410,980,440,55]},
 {label:'Interactive',color:'#d582b8',data:[0,40,250,610,280,35]},
 {label:'Video',color:'#b49cde',data:[0,10,110,250,110,15]},
];
export function overviewHTML({icon,button,polls,state}){
 const month=state.period===9?'October':'November';
 const answered=28+Object.keys(state.completed).length;
 return `<main class="overview" id="main"><header class="overview-heading"><h1 class="month-heading">${month} <span>2026</span></h1><div class="period-control"><button class="icon-btn" aria-label="Previous month" data-action="period" data-period="9" ${state.period===9?'disabled':''}>${icon('alt-arrow-right-linear','flip')}</button><span>Monthly</span><button class="icon-btn" aria-label="Next month" data-action="period" data-period="10" ${state.period===10?'disabled':''}>${icon('alt-arrow-right-linear')}</button></div></header><div class="stats-grid"><section class="stat-card reward-stat"><p class="stat-label">Earned this month</p><h2 class="stat-value">5,340 <small>pts</small></h2><p class="stat-change"><strong>+12%</strong> vs last month</p><img class="reward-card-art" src="/assets/ember/reward-cards.png" alt="Poll Pilled perspective points membership cards"></section><section class="stat-card"><p class="stat-label">Pending review</p><h2 class="stat-value">${state.pending.toLocaleString()} <small>pts</small></h2><p class="stat-change"><strong>3 answers</strong> in review</p></section><section class="stat-card"><p class="stat-label">Polls answered</p><h2 class="stat-value">${answered}</h2><p class="stat-change"><strong>+8</strong> vs last month</p></section></div><div class="analytics-grid"><section class="card chart-card" aria-label="Sample points earned by poll format"><div class="chart-heading"><div><p>Points earned</p><h2 class="chart-total">${state.points.toLocaleString()} <span class="muted" style="font-size:15px">pts</span></h2><p class="chart-period"><span>12% ↑</span> vs September</p></div><span class="subtle-badge">Sample activity</span></div><div class="chart-wrap"><canvas id="earnings-chart" role="img" aria-label="Sample points activity from May to October, broken down into image, classic, audio, interactive and video polls. Image polls are the largest contributor."></canvas></div><div class="chart-legend">${series.map(s=>`<span><i class="topic-dot" style="--dot:${s.color}"></i>${s.label}</span>`).join('')}</div></section><aside class="card format-stats"><h2>Your favourite formats</h2>${[['Image comparisons',11,76,'#edc04c'],['Classic polls',8,55,'#50c3a2'],['Audio polls',4,28,'#80b6ef'],['Interactive',3,20,'#d582b8'],['Video polls',2,14,'#b49cde']].map(([l,n,w,c])=>`<div class="format-stat"><div class="format-stat-header"><span>${l}</span><strong>${n}</strong></div><div class="format-bar"><div style="width:${w}%;--bar:${c}"></div></div></div>`).join('')}</aside></div><section class="recommended"><div class="section-heading"><h2>A few good questions for you</h2><button class="link row" data-nav="discover">View all polls ${icon('alt-arrow-right-linear','sm')}</button></div><div class="recommend-grid">${polls.slice(0,3).map(p=>`<button class="recommend-card" data-action="open-poll" data-id="${p.id}"><img src="${p.thumb}" alt=""><span><strong>${p.title}</strong><small>${p.seconds} sec · +${p.reward} pts</small></span></button>`).join('')}</div></section><p class="overview-footnote">Interactive prototype · Sample activity and rewards. No real payments or AI requests.</p></main>`;
}
export function mountOverviewChart(state){
 if(chart){chart.destroy();chart=null;}
 const canvas=document.querySelector('#earnings-chart');if(!canvas)return;
 const dark=document.documentElement.dataset.theme==='dark';
 chart=new Chart(canvas,{type:'line',data:{labels:['May','Jun','Jul','Aug','Sep',state.period===9?'Oct':'Nov'],datasets:series.map(s=>({label:s.label,data:s.data,borderColor:s.color,borderWidth:2,pointRadius:0,pointHoverRadius:4,pointBackgroundColor:s.color,tension:.42,fill:false}))},options:{responsive:true,maintainAspectRatio:false,animation:{duration:state.motion&&!matchMedia('(prefers-reduced-motion: reduce)').matches?550:0,easing:'easeOutCubic'},interaction:{mode:'index',intersect:false},layout:{padding:{top:8,right:4}},plugins:{legend:{display:false},tooltip:{backgroundColor:dark?'#252525':'#fff',titleColor:dark?'#ddd':'#222',bodyColor:dark?'#aaa':'#444',borderColor:dark?'#444':'#ccc',borderWidth:1,padding:12,cornerRadius:7,titleFont:{family:'system-ui, sans-serif',size:12,weight:'normal'},bodyFont:{family:'system-ui, sans-serif',size:11},callbacks:{label:c=>`${c.dataset.label}: ${c.formattedValue} pts`}}},scales:{x:{border:{display:false},grid:{display:false},ticks:{color:dark?'#777':'#777',font:{family:'system-ui, sans-serif',size:10},maxRotation:0}},y:{min:0,max:2000,border:{display:false},ticks:{stepSize:500,color:dark?'#777':'#777',padding:12,font:{family:'system-ui, sans-serif',size:10},callback:v=>v===0?'0':`${v/1000}k`},grid:{color:dark?'#2b2b2b':'#e5e5e5',drawTicks:false}}}}});
}
